<p class="text-muted small">Saving <?= $entry === null ? 'creates revision 1' : 'creates a new revision' ?>. Existing survey copies and earlier revisions are never edited.</p>
<form method="POST" action="<?= esc($formAction) ?>" data-modal-submit x-data="{ question: <?= esc(json_encode($question, JSON_HEX_TAG | JSON_HEX_AMP | JSON_HEX_APOS | JSON_HEX_QUOT), 'attr') ?> }">
<?= csrf_field() ?><?php if ($entry !== null): ?><input type="hidden" name="version" value="<?= (int) $entry['version'] ?>"><?php endif; ?>
<div class="mb-3"><label class="form-label" for="bankQuestionText">Question text</label><textarea id="bankQuestionText" class="form-control" name="question[label]" x-model="question.label" maxlength="500" rows="3" required></textarea></div>
<div class="row g-3 mb-3"><div class="col-md-6"><label for="bankQuestionCategory" class="form-label">Category</label><input id="bankQuestionCategory" name="category" maxlength="80" required class="form-control" value="<?= esc($entry['category'] ?? '') ?>" placeholder="e.g. Service feedback"></div>
<div class="col-md-6"><label for="bankQuestionAudience" class="form-label">Intended audience</label><select id="bankQuestionAudience" name="audience" class="form-select"><?php foreach (['all' => 'Students and employees', 'students' => 'Students', 'employees' => 'Employees'] as $value => $label): ?><option value="<?= esc($value) ?>" <?= ($entry['audience'] ?? 'all') === $value ? 'selected' : '' ?>><?= esc($label) ?></option><?php endforeach; ?></select></div></div>
<div class="mb-3"><label for="bankQuestionType" class="form-label">Answer type</label><select id="bankQuestionType" name="question[type]" class="form-select" x-model="question.type" @change="question.options = ['single','multiple'].includes(question.type) ? ['', ''] : []"><option value="text">Text (up to 2,000 characters)</option><option value="single">Single choice</option><option value="multiple">Multiple choice</option><option value="rating">Rating (1–5)</option></select></div>
<input type="hidden" name="question[required]" :value="question.required ? '1' : '0'">
<label class="form-check mb-3"><input type="checkbox" class="form-check-input" x-model="question.required"><span class="form-check-label">Required by default</span></label>
<template x-for="(option, index) in question.options" :key="index"><div class="input-group mb-2"><input class="form-control" :aria-label="'Option ' + (index + 1)" :name="'question[options][' + index + ']'" x-model="question.options[index]" maxlength="200" required><button type="button" class="btn btn-outline-secondary" :disabled="question.options.length <= 2" @click="question.options.splice(index, 1)">Remove option</button></div></template>
<button type="button" class="btn btn-outline-primary btn-sm mb-3" x-show="['single','multiple'].includes(question.type)" :disabled="question.options.length >= 10" @click="question.options.push('')">Add option</button>
<div class="mb-3"><label for="bankReviewNote" class="form-label">Author review note (optional)</label><textarea id="bankReviewNote" name="review_note" class="form-control" rows="3" maxlength="1000" placeholder="Intended use, sensitivity or licensing considerations. Do not include personal information."><?= esc($entry['review_note'] ?? '') ?></textarea><small class="text-muted">Visible to survey authors only; not copied into respondents’ questions. A bank entry does not establish clinical validity.</small></div>
<div class="form-actions"><a class="btn btn-outline-secondary" href="<?= esc($cancelUrl) ?>" data-app-modal-close>Cancel</a><button class="btn btn-primary" type="submit">Save bank question</button></div>
</form>
